using HomeLibrary;
using Microsoft.AspNetCore.DataProtection;
using Microsoft.Data.Sqlite;
using System.Text.Json;
public static class AccountDeletionTests {
 static void Check(bool value,string message){if(!value)throw new Exception("Deletion: "+message);Console.WriteLine("PASS "+message);}
 static JsonElement Json(object value)=>JsonSerializer.SerializeToElement(value,Library.Json);
 static void Bad(Action work,int? status=null){try{work();throw new Exception("Expected deletion rejection");}catch(LibraryError error){if(status!=null)Check(error.Status==status,"deletion rejection status");}}
 public static async Task Run(string directory,IDataProtectionProvider protection){
  Directory.CreateDirectory(directory);using var store=new Store(directory,protection);using var accounts=new BorrowerAccounts(directory);using var vault=new BorrowerVault(directory);var access=new ReadingAccess(directory,"https://library.example",protection);using var reminders=new Reminders(directory,protection,store,new NeverSend());
  JsonElement Change(string action,object value)=>Json(store.Apply(new(action,Json(value),store.Read().Revision,Guid.NewGuid().ToString()))).GetProperty("result");
  BorrowerAccount Create(string username,string name,string contact){var account=accounts.Register(new(username,"Long account testing passphrase!",name,contact,""));return accounts.Approve(new(account.Id),store);}
  AccountDeletionInput Review(AccountDeletionInput input){var preview=store.PreviewAccountDeletion(accounts.Get(input.AccountId),input,accounts.List());return input with{PreviewToken=preview.PreviewToken,Confirmation=preview.Username};}
  async Task Delete(AccountDeletionInput input){using var pause=await reminders.Pause(default);accounts.Delete(input,store,access,reminders);}
  var a=Create("erase.reader","Erase Reader","erase@example.com");var other=Create("keep.reader","Keep Reader","keep@example.com");
  Change("addBook",new{isbn="9780140328721",title="Matilda",author="Roald Dahl"});Change("checkout",new{copyId="BK-0001",borrowerId=a.BorrowerId,checkoutDate=Library.Today,dueDate=Library.Today});
  var session=accounts.Login(new(a.Username,"Long account testing passphrase!"));var reset=accounts.ResetLink(a.Id,"https://library.example").Split("#reset=")[1];var personal=Json(access.Change(a.ReaderId,"enable")).GetProperty("url").GetString()!.Split('#')[1];
  var input=Review(new(a.Id,true));Bad(()=>accounts.Delete(input,store,access,reminders));Check(accounts.Get(a.Id).Status=="active"&&accounts.Resolve(session)!=null,"active-loan protection rejects full erasure before blocking the account");
  // Account-only deletion is allowed with an active loan and retains household records.
  await Delete(Review(new(a.Id)));Check(accounts.PendingVaultDeletes().Contains(a.Id),"credential deletion durably queues encrypted-vault cleanup");using(var reopened=new BorrowerAccounts(directory))Check(reopened.PendingVaultDeletes().Contains(a.Id),"vault cleanup survives a restart before erasure");vault.AfterDeletion(new{warnings=Array.Empty<string>()},a.Id,accounts);Check(!accounts.PendingVaultDeletes().Contains(a.Id),"successful vault cleanup clears only its deletion marker");Check(accounts.List().All(x=>x.Id!=a.Id)&&accounts.Resolve(session)==null&&access.Resolve(personal)==null,"account-only deletion removes sign-in/session/personal QR access");Bad(()=>accounts.Reset(new(reset,"Another long passphrase!")),401);Check(store.Read().State.Loans.Single().ReturnedDate==null&&store.Read().State.Readers.Any(r=>r.Id==a.ReaderId),"account-only deletion keeps active loans and reading profile");
  var replacement=accounts.Register(new(a.Username,"Fresh account passphrase!",a.Name,a.Contact,""));Check(replacement.Status=="pending"&&replacement.Id!=a.Id,"deleted username can be registered afresh without inheriting access");Bad(()=>accounts.Delete(input,store,access,reminders),404);
  // Relink operational borrower history without inheriting another account’s private reading.
  Bad(()=>accounts.Approve(new(replacement.Id,a.ReaderId),store),403);
  var previousReader=a.ReaderId;a=accounts.Approve(new(replacement.Id,BorrowerId:a.BorrowerId),store);Check(a.ReaderId!=previousReader,"replacement account gets fresh private profile while retaining operational borrower link");Change("returnBook",new{copyId="BK-0001"});Change("saveReading",new{readerId=a.ReaderId,copyId="BK-0001",status="reading",notes="DELETE THIS PRIVATE NOTE"});Change("saveReading",new{readerId=other.ReaderId,copyId="BK-0001",status="want",notes="KEEP THIS PRIVATE NOTE"});
  store.PersonalRequest(a.ReaderId,new("BK-0001",a.Name,a.Contact,"Private linked request",Guid.NewGuid().ToString(),"9780140328721","Matilda"));
  Change("declineRequest",new{requestId=store.Read().State.Requests.Single().Id});
  var ownGuest=Json(store.SubmitRequest(new("BK-0001","Erase Guest",a.Contact,"Delete guest message",Guid.NewGuid().ToString(),"9780140328721","Matilda"))).GetProperty("id").GetString()!;
  Change("declineRequest",new{requestId=ownGuest});
  var otherGuest=Json(store.SubmitRequest(new("BK-0001","Different Person",a.Contact,"Keep guest message",Guid.NewGuid().ToString(),"9780140328721","Matilda"))).GetProperty("id").GetString()!;
  var plan=Review(new(a.Id,true));Bad(()=>accounts.Delete(plan with{Confirmation="wrong"},store,access,reminders));Change("setLibraryName",new{libraryName="Updated library"});Bad(()=>accounts.Delete(plan,store,access,reminders),409);Check(accounts.Get(a.Id).Status=="active","stale deletion preview cannot erase or block an account");
  Bad(()=>Review(new(a.Id,true,ReaderId:other.ReaderId)));Check(store.Read().State.Readers.Count==3,"cannot erase records bound to a different sign-in account");
  // Pending/unlinked account deletion can explicitly include a verified old profile.
  accounts.Block(a.Id);accounts.Unblock(a.Id);Change("removeBorrower",new{borrowerId=a.BorrowerId});Check(store.Read().State.RecycleBin.Any(r=>r.Borrower?.Id==a.BorrowerId),"fixture has borrower recovery data");
  var backups=Path.Combine(directory,"backups");store.Backup(store.Read().State,"manual-retained-test");var safety=Path.Combine(Path.GetDirectoryName(directory)!,"upgrade-backups");Directory.CreateDirectory(safety);File.WriteAllText(Path.Combine(safety,"before-update-test.zip"),"private safety fixture");File.WriteAllText(Path.Combine(backups,"keep-unrelated.txt"),"unrelated file");
  var erasedQr=Json(access.Change(a.ReaderId,"enable")).GetProperty("url").GetString()!.Split('#')[1];var keptQr=Json(access.Change(other.ReaderId,"enable")).GetProperty("url").GetString()!.Split('#')[1];
  File.WriteAllText(Path.Combine(backups,"partial.hlbackup.tmp"),"old partial backup fixture");
  using(var db=new SqliteConnection(new SqliteConnectionStringBuilder{DataSource=Path.Combine(directory,"reminders.sqlite")}.ToString())){db.Open();using var cmd=db.CreateCommand();cmd.CommandText="INSERT INTO deliveries VALUES('delete-delivery',$loan,'BK-0001','due',$due,$at,'sent');INSERT INTO deliveries VALUES('keep-delivery','other-loan','BK-0001','due',$due,$at,'sent');";cmd.Parameters.AddWithValue("$loan",store.Read().State.Loans.Single().Id);cmd.Parameters.AddWithValue("$due",Library.Today);cmd.Parameters.AddWithValue("$at",DateTimeOffset.UtcNow.ToString("O"));cmd.ExecuteNonQuery();}
  var selection=new AccountDeletionInput(a.Id,true,ReaderId:a.ReaderId,GuestRequestIds:[ownGuest],RemoveBackups:true);var preview=store.PreviewAccountDeletion(accounts.Get(a.Id),selection,accounts.List());Check(preview.Borrowers.Length==1&&preview.ReadingEntries==1&&preview.ReturnedLoans==1&&preview.Requests==2&&preview.GuestRequests.Length==2,"preview counts only linked records and explicitly selected guest requests");
  await Delete(Review(selection));var state=store.Read().State;Library.Validate(state);Check(state.Books.Single().Title=="Matilda"&&state.Borrowers.All(b=>b.Id!=a.BorrowerId)&&state.Readers.All(r=>r.Id!=a.ReaderId)&&state.Loans.Count==0&&state.RecycleBin.All(r=>r.Borrower?.Id!=a.BorrowerId),"full erasure removes selected borrower/profile/loans/recovery and keeps physical books");
  Check(state.ReadingEntries.Single().Notes=="KEEP THIS PRIVATE NOTE"&&state.Requests.Single().Id==otherGuest&&state.Requests.Single().Message=="Keep guest message"&&accounts.Get(other.Id).Status=="active","other reader notes, guest requests and sign-in remain intact");
  Check(access.Resolve(erasedQr)==null&&access.Resolve(keptQr)==other.ReaderId,"full erasure revokes selected private QR while other reader QR remains valid");
  using(var db=new SqliteConnection(new SqliteConnectionStringBuilder{DataSource=Path.Combine(directory,"reminders.sqlite")}.ToString())){db.Open();using var cmd=db.CreateCommand();cmd.CommandText="SELECT id FROM deliveries";Check((string?)cmd.ExecuteScalar()=="keep-delivery","erased loan reminder metadata removed while unrelated delivery metadata stays");}
  Check(accounts.List().All(x=>x.Id!=a.Id)&&store.DeletionBackups().Length==0&&File.Exists(Path.Combine(backups,"keep-unrelated.txt")),"explicit backup cleanup removes owned backup patterns without unrelated files");
  using(var db=new SqliteConnection(new SqliteConnectionStringBuilder{DataSource=Path.Combine(directory,"library.sqlite")}.ToString())){db.Open();using var cmd=db.CreateCommand();cmd.CommandText="SELECT result FROM receipts";using var rows=cmd.ExecuteReader();var retained=new List<string>();while(rows.Read())retained.Add(rows.GetString(0));Check(retained.All(x=>!x.Contains("DELETE THIS PRIVATE NOTE")&&!x.Contains(a.ReaderId)&&!x.Contains(a.BorrowerId))&&retained.Any(x=>x.Contains("KEEP THIS PRIVATE NOTE")),"personal mutation receipts erased while unrelated idempotent receipts stay intact");}
  store.ScheduledBackup(-1);foreach(var file in Directory.GetFiles(backups,"*.hlbackup")){var saved=store.RestoreEncrypted(File.ReadAllBytes(file));Check(saved.Readers.All(r=>r.Id!=a.ReaderId)&&saved.ReadingEntries.All(e=>e.ReaderId!=a.ReaderId),"new scheduled backup cannot reintroduce erased data");}
  using(var restarted=new BorrowerAccounts(directory))Check(restarted.List().All(x=>x.Id!=a.Id),"deleted credentials stay absent after restart");
  var fresh=accounts.Register(new(a.Username,"Third long passphrase!",a.Name,a.Contact,""));await Delete(Review(new(fresh.Id,true)));Check(accounts.List().Count==1,"unlinked pending account can be deleted without touching any household records");
 }
 sealed class NeverSend:IReminderSender {public Task Send(ReminderConfiguration settings,ReminderMail mail,CancellationToken stop)=>throw new Exception("No email should be sent by deletion tests.");}
}
